query webhookQuery($objectid: ID!) {
  node(id: $objectid) {
    ... on Event {
      id
      legacyId
      code
      title
      lifecycleState
      location { name }
      remoteMeeting { type url }
      remoteMeetingHostContact { id }
    }
  }
}

