// Nothing to do: the classroom is already set to Teams with a host, or uses another provider.
// Stops the workflow from overwriting a classroom that was set up another way.
const node = $json.payload.node;
return [{
  json: {
    status: 'skipped',
    timestamp: $now.toISO(),
    eventId: node.id,
    eventCode: node.code,
    eventTitle: node.title,
    reason: 'Virtual classroom already configured (Teams host assigned or non-Teams provider already set); left unchanged',
    remoteMeetingUrl: node.remoteMeeting?.url ?? null,
  },
}];

