={{ JSON.stringify({
  query: `mutation AddPersonnel($input: EventStaffInput!) {
    event {
      addStaff(input: $input) {
        errors { label message value }
        event { id staff { edges { node { id contact { id } staffRole { id name } } } } }
      }
    }
  }`,
  variables: {
    input: {
      eventId: $json.eventId,
      contactId: $json.contactId,
      staffRoleId: $json.staffRoleId
    }
  }
}) }}

