// Final status log. Add Slack, email or Google Sheets after this node if needed.
const inputs = $('Set Inputs').first().json;
const addP = $('1. Add Personnel').first().json;
const cfg = $('2. Configure Virtual Classroom').first().json;
const host = $('3. Assign Host').first().json;

const errors = [];
const collect = (resp, path, label) => {
  if (!resp) { errors.push(`${label}: no response`); return; }
  if (resp.errors) errors.push(...resp.errors.map(e => `${label}: ${e.message || JSON.stringify(e)}`));
  const inner = path(resp);
  if (inner && inner.length) errors.push(...inner.map(e => `${label}: ${e.message} (${e.label ?? ''})`));
};
collect(addP, r => r.data?.event?.addStaff?.errors, 'addPersonnel');
collect(cfg, r => r.data?.event?.update?.errors, 'configureClassroom');
collect(host, r => r.data?.event?.update?.errors, 'assignHost');

return [{
  json: {
    status: errors.length ? 'error' : 'success',
    timestamp: $now.toISO(),
    eventId: inputs.eventId,
    eventCode: inputs.eventCode,
    eventTitle: inputs.eventTitle,
    remoteMeetingType: cfg.data?.event?.update?.event?.remoteMeeting?.type ?? null,
    remoteMeetingUrl: host.data?.event?.update?.event?.remoteMeeting?.url ?? null,
    errors,
  },
}];

